import java.io.*;
import java.util.*;

public class Main {

    static long cross(long ax, long ay, long bx, long by) {
        return ax * by - ay * bx;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String ln;
        while ((ln = br.readLine()) != null) sb.append(ln).append(' ');
        StringTokenizer tz = new StringTokenizer(sb.toString());

        long[] X = new long[8], Y = new long[8];
        for (int i = 1; i <= 7; i++) {
            X[i] = Long.parseLong(tz.nextToken());
            Y[i] = Long.parseLong(tz.nextToken());
        }

        long ax = X[2] - X[1], ay = Y[2] - Y[1]; // P1 -> P2
        long bx = X[3] - X[1], by = Y[3] - Y[1]; // P1 -> P3
        long dx = X[3] - X[2], dy = Y[3] - Y[2]; // P2 -> P3

        boolean ok = true;

        // 1) angulo P2P1P3 agudo (0 < angulo < 90 graus)
        ok &= (ax * bx + ay * by) > 0;
        ok &= (ax * by - ay * bx) != 0;

        // 2) |P1P2| == |P1P3|
        ok &= (ax * ax + ay * ay) == (bx * bx + by * by);

        // 3) P2, P3, P4, P5 colineares
        ok &= cross(dx, dy, X[4] - X[2], Y[4] - Y[2]) == 0;
        ok &= cross(dx, dy, X[5] - X[2], Y[5] - Y[2]) == 0;

        // 4) pontos medios de P2P3 e P4P5 coincidem
        ok &= (X[2] + X[3] == X[4] + X[5]) && (Y[2] + Y[3] == Y[4] + Y[5]);

        // 5) |P2P3| > |P4P5|
        ok &= (dx * dx + dy * dy) > ((X[5] - X[4]) * (X[5] - X[4]) + (Y[5] - Y[4]) * (Y[5] - Y[4]));

        // 6) P4P6 e P5P7 perpendiculares a P2P3
        ok &= ((X[6] - X[4]) * dx + (Y[6] - Y[4]) * dy) == 0;
        ok &= ((X[7] - X[5]) * dx + (Y[7] - Y[5]) * dy) == 0;

        // 7) |P4P6| == |P5P7|
        long p46 = (X[6] - X[4]) * (X[6] - X[4]) + (Y[6] - Y[4]) * (Y[6] - Y[4]);
        long p57 = (X[7] - X[5]) * (X[7] - X[5]) + (Y[7] - Y[5]) * (Y[7] - Y[5]);
        ok &= p46 == p57;

        // 8) P1 e P6 em lados opostos da reta que contem P2P3
        long c1 = cross(dx, dy, X[1] - X[2], Y[1] - Y[2]);
        long c6 = cross(dx, dy, X[6] - X[2], Y[6] - Y[2]);
        ok &= ((c1 > 0 && c6 < 0) || (c1 < 0 && c6 > 0));

        System.out.println(ok ? "S" : "N");
    }
}
